function initSinglePostToc(){const e=document.querySelector(".single-post-toc");if(!e||"undefined"==typeof IntersectionObserver)return;const t=e.querySelectorAll(".single-post-toc__link");if(!t.length)return;const n=new Map,o=[];if(t.forEach(e=>{const t=e.dataset.tocAnchor,s=t?document.getElementById(t):null;s&&(n.set(s,e),o.push(s))}),!o.length)return;const s=e=>{t.forEach(e=>e.classList.remove("is-active"));const o=n.get(e);o&&o.classList.add("is-active")},c=new IntersectionObserver(e=>{e.forEach(e=>{e.isIntersecting&&s(e.target)})},{rootMargin:"-15% 0px -70% 0px",threshold:0});o.forEach(e=>c.observe(e)),s(o[0])}document.addEventListener("DOMContentLoaded",()=>{initSinglePostToc()});